    39	pub async fn run_game(opts: &GamesSubCommand) -> anyhow::Result<()> {
    40	    match opts {
    41	        GamesSubCommand::Wordle(args) => {
    42	            let mut twitch = get_twitch_chat(&args.twitch).await?;
    43	            let (chat_sender, chat_receiver) = tokio::sync::mpsc::unbounded_channel();
    44	            let channel = args.twitch.channel.clone();
    45	            tokio::spawn(async move {
    46	                match twitch.run(chat_sender, channel).await {
    47	                    Ok(()) => {}
    48	                    Err(e) => tracing::error!(error = %e, "Twitch chat task exited with error"),
    49	                }
    50	            });
    51	
    52	            let sqlite_pool =
    53	                sql_common::setup::setup_sqlite_migrations(args.db_path.clone(), &MIGRATIONS)
    54	                    .await?;
    55	            let word_list = WordList::from(args.word_list.as_str());
    56	
    57	            // Anathema's `runtime.run` blocks a thread for the whole session. Running it on a
    58	            // Tokio worker can strand `tokio::spawn` tasks (e.g. `game_loop`, IRC) on that same
    59	            // worker, so drive the TUI from the blocking pool instead.
    60	            tokio::task::spawn_blocking(move || {
    61	                crate::wordle::game::start_game(chat_receiver, word_list, sqlite_pool)
    62	            })
    63	            .await
