   383	/// Returns whether any stored score changed.
   384	async fn award_points(
   385	    leader_board: &Pool<Sqlite>,
   386	    players: Vec<&Player>,
   387	    points: u32,
   388	) -> anyhow::Result<bool> {
   389	    if points == 0 {
   390	        return Ok(false);
   391	    }
   392	    let mut awarded = false;
   393	    for player in players.into_iter().filter(|player| player.is_scored()) {
   394	        awarded = true;
   395	        let score = add_points(
   396	            leader_board,
   397	            player.platform,
   398	            &player.id,
   399	            &player.name,
   400	            i64::from(points),
   401	        )
   402	        .await?;
   403	        tracing::info!(
   404	            player = %player.name,
   405	            points,
   406	            total_points = score.total_points,
   407	            "Wordle points awarded"
   408	        );
   409	    }
   410	    Ok(awarded)
   411	}
