151	/// Log file path: `BRUCE_LOG`, then `NULL_TWITCH_LOG`, else `bruce.log`.
152	/// Logs go to stderr and to this file (append mode); use the file when a TUI owns the terminal.
153	fn install_tracing() -> anyhow::Result<()> {
154	    use tracing_error::ErrorLayer;
155	    use tracing_subscriber::prelude::*;
156	    use tracing_subscriber::{fmt, EnvFilter};
157	
158	    let log_path: PathBuf = std::env::var_os("BRUCE_LOG")
159	        .or_else(|| std::env::var_os("NULL_TWITCH_LOG"))
160	        .filter(|s| !s.is_empty())
161	        .map(PathBuf::from)
162	        .unwrap_or_else(|| PathBuf::from("bruce.log"));
163	
164	    if let Some(dir) = log_path.parent() {
